// Linear interpolation
function lerp(start, end, t) {
    return start + (end - start) * t;
}

// Smooth camera follow
class Camera {
    update(target, dt) {
        // Move 10% closer each frame (adjust for dt)
        const factor = 1 - Math.pow(0.1, dt);
        this.x = lerp(this.x, target.x - canvas.width/2, factor);
        this.y = lerp(this.y, target.y - canvas.height/2, factor);
    }
}

