// Easing function library
const Easing = {
    linear: t => t,
    easeInQuad: t => t * t,
    easeOutQuad: t => 1 - (1 - t) * (1 - t),
    easeInOutQuad: t => t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2,
    easeOutBounce: t => {
        const n1 = 7.5625, d1 = 2.75;
        if (t < 1 / d1) return n1 * t * t;
        else if (t < 2 / d1) return n1 * (t -= 1.5 / d1) * t + 0.75;
        else if (t < 2.5 / d1) return n1 * (t -= 2.25 / d1) * t + 0.9375;
        return n1 * (t -= 2.625 / d1) * t + 0.984375;
    }
};

// Tween class for reusable animations
class Tween {
    constructor(target, property, to, duration, easing = Easing.easeOutQuad) {
        this.target = target;
        this.property = property;
        this.from = target[property];
        this.to = to;
        this.duration = duration;
        this.easing = easing;
        this.elapsed = 0;
        this.active = true;
    }

    update(dt) {
        if (!this.active) return;
        this.elapsed += dt;
        const t = Math.min(this.elapsed / this.duration, 1);
        this.target[this.property] = this.from + (this.to - this.from) * this.easing(t);
        if (t >= 1) this.active = false;
    }
}

// Usage: Bounce a UI element into view
const button = { y: -100 };
const tween = new Tween(button, 'y', 200, 1.0, Easing.easeOutBounce);

class SpriteAnimation {
    constructor(sheet, frameWidth, frameHeight, frameCount, fps) {
        this.sheet = sheet;
        this.frameWidth = frameWidth;
        this.frameHeight = frameHeight;
        this.frameCount = frameCount;
        this.frameDuration = 1 / fps;
        this.currentFrame = 0;
        this.timer = 0;
    }

    update(dt) {
        this.timer += dt;
        if (this.timer >= this.frameDuration) {
            this.currentFrame = (this.currentFrame + 1) % this.frameCount;
            this.timer = 0;
        }
    }

    draw(ctx, x, y) {
        const sx = this.currentFrame * this.frameWidth;
        const sy = 0; // Single row for now
        ctx.drawImage(
            this.sheet,
            sx, sy, this.frameWidth, this.frameHeight, // Source
            x, y, this.frameWidth, this.frameHeight   // Destination
        );
    }
}

