class GroundedState {
    constructor(machine) {
        this.machine = machine;
        this.player = machine.player;
    }

    enter() {
        this.player.canJump = true;
        this.player.animation = 'run';
    }

    update(dt) {
        if (!this.player.grounded) {
            this.machine.changeState(new FallingState(this.machine));
            return;
        }

        if (input.isPressed('Space')) {
            this.machine.changeState(new JumpingState(this.machine));
            return;
        }

        if (input.isDown('ArrowRight')) {
            this.player.vx += this.player.acceleration * dt;
        }
    }
}

class JumpingState {
