    update(dt) {
        if (this.player.vy > 0) {
            this.machine.changeState(new FallingState(this.machine));
        }
    }
}

// ECS Core
class World {
    constructor() {
        this.nextEntityId = 0;
        this.components = new Map(); // componentName -> Map(entityId, data)
        this.systems = [];
        this.entitiesToRemove = [];
    }

    createEntity() {
        return this.nextEntityId++;
    }

    addComponent(entityId, componentName, data) {
        if (!this.components.has(componentName)) {
            this.components.set(componentName, new Map());
        }
        this.components.get(componentName).set(entityId, data);
    }

    getComponent(entityId, componentName) {
        return this.components.get(componentName)?.get(entityId);
    }

    hasComponents(entityId, ...names) {
        return names.every(name => 
            this.components.get(name)?.has(entityId)
        );
    }

    removeEntity(entityId) {
        this.entitiesToRemove.push(entityId);
    }

    update(dt) {
        for (const system of this.systems) {
            system.update(this, dt);
        }

        // Cleanup removed entities
        for (const entityId of this.entitiesToRemove) {
            for (const componentMap of this.components.values()) {
                componentMap.delete(entityId);
            }
        }
        this.entitiesToRemove = [];
    }

    draw(ctx) {
        for (const system of this.systems) {
            if (system.draw) system.draw(this, ctx);
        }
    }
}

// Component definitions (just data structures)
const Position = (x, y) => ({ x, y });
